import {DEFAULT_RULES,SEATS,SPEAKER_CRITERIA,timerDisplay,scoreScorecard} from './debate-domain.js';
import {DebateMedia} from './debate-media.js';
import {eventInstant,eventLocalInput} from './debate-dates.js';

const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => JSON.parse(JSON.stringify(value));
const id = () => crypto.randomUUID();
const state = {session:null,client:null,event:null,matchId:null,panel:'overview',busy:false,sync:null,observerPage:0,tiles:new Map(),lastStage:null,judgeDirty:false,pending:null,accountGeneration:0,mutedPeople:new Set(),blockedPeople:new Set(),pinnedTile:null,messageHistory:new Map(),historyDone:new Set(),freshInvite:null,viewGeneration:0};
const localRehearsal = ['127.0.0.1','localhost'].includes(location.hostname) && globalThis.DEBATE_LOCAL_REHEARSAL === true;
const config = globalThis.DueDiligencePhase2Config || globalThis.DUE_DILIGENCE_PHASE2_CONFIG || {};
let apiBase = localRehearsal ? location.origin : (config.workerUrl || config.apiBaseUrl || '');
let deviceId = id();
const serverNow = () => state.sync ? Math.floor(state.sync.server + performance.now()-state.sync.local) : 0;
const usableMatches = () => (state.event?.matches||[]).filter(m=>!m.officialRecordsExpired);
const currentMatch = () => usableMatches().find(m=>m.id === state.matchId) || usableMatches().find(m=>m.id === state.event?.activeMatchId) || usableMatches()[0];
const me = () => state.event?.members.find(p=>p.id === state.event.myId);
const host = () => !!state.event && (state.event.ownerId === state.event.myId || me()?.roles.some(r=>['host','cohost','organizer','co_host'].includes(r)));
const moderationOfficial = () => { const m=currentMatch(); return m && (host() || [m.moderatorId,m.chiefId].includes(state.event.myId)); };
const official = () => { const m=currentMatch(); return m && (host() || [m.moderatorId,m.timekeeperId,m.chiefId].includes(state.event.myId)); };
const panelAdmin = () => host() || currentMatch()?.chiefId===state.event?.myId;
const clearSensitiveViews = () => {state.viewGeneration++;for(const form of ['message-form','evidence-form'])$(form).reset();for(const name of ['judge-content','results-content','messages','evidence-list','live-motion','stage-controls','active-match','stage-label','speaker-label','run-of-show','private-space-controls','affirmative-name','negative-name','next-stage','presentation','stage-announcement'])$(name).replaceChildren();delete $('stage-controls').dataset.renderKey;for(const tile of state.tiles.values())tile.remove();state.tiles.clear();};
const mediaIdentity = personId => currentMatch()?.mediaParticipants?.find(p=>p.userId===personId)?.identity || '';
const personName = personId => state.event?.members.find(p=>p.id === personId)?.displayName || 'Unassigned';
const sideName = side => side === 'affirmative' ? 'Affirmative' : side === 'negative' ? 'Negative' : 'Unresolved';
const teamName = teamId => state.event?.teams.find(t=>t.id===teamId)?.name || 'Awaiting predecessor';
const awardNames = {bestSpeaker:'Best Speaker',bestInterpellator:'Best Interpellator',bestRebuttalSpeaker:'Best Rebuttalist',bestDebater:'Best Debater'};
const humanState = value => String(value || 'Unavailable').toLowerCase().replace(/_/g,' ').replace(/^./,c=>c.toUpperCase());
const myTeamSide = () => {const m=currentMatch();return ['affirmative','negative'].find(side=>m?.teamIds?.[side]===me()?.teamId) || (Object.keys(m?.seats||{}).find(seat=>m.seats[seat]===state.event?.myId)?.[0]==='A'?'affirmative':Object.keys(m?.seats||{}).find(seat=>m.seats[seat]===state.event?.myId)?.[0]==='N'?'negative':null);};
const matchPayload = extra => ({matchId:currentMatch()?.id,...extra});
const option = (value,label,selected) => `<option value="${esc(value)}"${selected === value ? ' selected' : ''}>${esc(label)}</option>`;
const peopleOptions = (selected,empty=true) => `${empty?option('','Choose a participant',selected):''}${state.event.members.filter(p=>!p.removed).map(p=>option(p.id,p.displayName,selected)).join('')}`;
const button = (label,action,extra='',className='') => `<button type="button" data-action="${action}" ${extra} class="${className}">${esc(label)}</button>`;
const field = (label,name,value='',type='text',extra='') => `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const selectPerson = (label,name,value='') => `<label>${esc(label)}<select name="${name}">${peopleOptions(value)}</select></label>`;
const formatTime = value => value ? new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short',timeZone:state.event?.timezone || 'Asia/Manila'}).format(new Date(value)) : 'Unscheduled';

function publicErrorMessage(value) { const text=String(value || '').trim(); return !text || /^[A-Z][A-Z0-9_]{2,}(?::[ \t].*)?$/.test(text) ? 'This action could not be completed. Refresh the event and try again. If it continues, contact the organizer.' : text; }
const deliveryName = type => ({export:'Download',mail:'Results email',invitation_mail:'Invitation email',media:'Room connection',delete_evidence:'Evidence removal',delete_export:'Download removal'})[type] || 'Event request';
function status(message,error=false) { $('status').textContent=error?publicErrorMessage(message):message; $('status').dataset.error=String(error); }
async function request(path,body) {
  if (!apiBase) throw new Error('The Debate Room connection is not configured. Your other Due Diligence features remain available.');
  const accountGeneration=state.accountGeneration,viewGeneration=state.viewGeneration; const began=performance.now(); const controller=new AbortController(); const timeout=setTimeout(()=>controller.abort(),18000);
  try {
    const response=await fetch(`${apiBase.replace(/\/$/,'')}${path}`,{method:body?'POST':'GET',cache:'no-store',credentials:'omit',
      headers:{Authorization:`Bearer ${state.session?.access_token || ''}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal});
    const result=await response.json().catch(()=>null);
    if(accountGeneration!==state.accountGeneration||viewGeneration!==state.viewGeneration){const error=new Error('Your account or event context changed; the old response was discarded. Refresh the event to check any saved action.');error.status=409;error.code='VIEW_CHANGED';throw error;}
    if (!response.ok || result?.ok === false) { const error=new Error(result?.error?.message || 'The action could not be confirmed. Refresh to check your saved work.'); error.code=result?.error?.code; error.details=result?.error?.details; error.status=response.status; throw error; }
    if (Number.isFinite(result.serverNow)) state.sync={server:result.serverNow+(performance.now()-began)/2,local:performance.now(),rtt:performance.now()-began};
    return result;
  } finally { clearTimeout(timeout); }
}
function adopt(event,force=false) {
  if (!event || state.event?.id === event.id && (event.revision < state.event.revision || !force && event.revision === state.event.revision)) return;
  const oldMe=me(),nextMe=event.members.find(p=>p.id===event.myId);
  const context=(person,match)=>[person?.admitted,person?.roles,person?.teamId,match?.judgeIds,match?.seats,match?.closingSeats,match?.captains,match?.ruleVersion];
  const changedAuthority=state.event?.id===event.id&&JSON.stringify(context(oldMe,currentMatch()))!==JSON.stringify(context(nextMe,event.matches.find(m=>m.id===state.matchId)));
  if(changedAuthority){clearSensitiveViews();$('dialog').close();$('dialog-fields').replaceChildren();$('context-change-note').hidden=false;$('context-change-note').textContent='Your roles, assignments or accepted rules changed. Review the current roster and rules before entering new scores. Unsaved values from the earlier context were discarded.';state.messageHistory.clear();state.historyDone.clear();clearTimeout(state.draftTimer);state.judgeDirty=false;force=true;}
  state.event=event; state.matchId=currentMatch()?.id || null;
  if(event.awaitingAdmission){clearSensitiveViews();state.messageHistory.clear();state.historyDone.clear();state.panel='overview';state.judgeDirty=false;clearTimeout(state.draftTimer);media.leave();for(const tile of state.tiles.values())tile.remove();state.tiles.clear();for(const name of ['judge-content','results-content','messages','evidence-list'])$(name).replaceChildren();}
  document.querySelectorAll('#event-tabs button').forEach(b=>b.disabled=!!event.awaitingAdmission&&b.dataset.panel!=='overview');
  $('event').hidden=false; $('lobby').hidden=true; $('event-title').textContent=event.title;
  $('event-meta').textContent=`${event.language} · ${event.timezone} · ${event.status}`;
  $('rehearsal-banner').hidden=!event.rehearsal;
  const fragment=new URLSearchParams({event:event.id}); if(state.matchId)fragment.set('match',state.matchId);
  history.replaceState(null,'',`${location.pathname}#${fragment}`);
  renderLive();
  guarded(reconcileMedia);
  if (force || !document.activeElement?.closest('form') && !state.judgeDirty) renderPanel();
}
async function refresh() {
  if (!state.event || state.busy) return;
  try { const result=await request(`/debate-room/snapshot?eventId=${encodeURIComponent(state.event.id)}`); adopt(result.event); }
  catch(error) { status(error.message,true); if(error.status===401)await signOutCleanup();else if(error.status===403||['NOT_MEMBER','EVENT_NOT_FOUND'].includes(error.code)){discardEventView();await media.leave();status('Your access to this event changed. Its private content has been cleared.',true);loadEvents().catch(()=>{});} }
}
async function command(name,payload={},eventId=state.event?.id) {
  if(navigator.onLine===false)throw new Error('Reconnect before changing the saved event.');
  if (state.busy) throw new Error('The previous action is still being confirmed.');
  const envelope={eventId,command:name,payload,expectedRevision:state.event&&state.event.id===eventId?state.event.revision:name==='join_public_event'?undefined:0,idempotencyKey:id()};
  state.busy=true; state.pending=envelope; status('Saving…');
  try {
    const result=await request('/debate-room/command',envelope); state.pending=null;
    if(result.event)adopt(result.event,true); status('Saved.'); return result.receipt?.result || {};
  } catch(error) {
    if(error.status)state.pending=null;
    status(`${error.message}${!error.status?' The response is unconfirmed; use Retry last action to safely recover its receipt.':''}`,true);
    throw error;
  } finally { state.busy=false; }
}
function discardEventView(){clearTimeout(state.draftTimer);clearSensitiveViews();state.event=null;state.matchId=null;state.judgeDirty=false;state.pending=null;state.freshInvite=null;state.messageHistory.clear();state.historyDone.clear();for(const name of ['overview-content','participants-content','rules-content','vote-content','schedule-content','help-content'])$(name).replaceChildren();for(const tile of state.tiles.values())tile.remove();state.tiles.clear();$('dialog').close();$('dialog-fields').replaceChildren();$('context-change-note').hidden=true;$('event').hidden=true;$('lobby').hidden=false;history.replaceState(null,'',location.pathname);}
async function retryPending() {
  if(!state.pending)return refresh();
  const result=await request('/debate-room/command',state.pending); state.pending=null; if(result.event)adopt(result.event,true); status('The saved action is confirmed.');
}
async function loadEvents() {
  const result=await request('/debate-room/events');
  loadDiscovery().catch(error=>{$('discover-events').textContent=error.message;});
  $('events').innerHTML=result.events.length?result.events.map(e=>`<article><h3>${esc(e.title)}</h3><p class="muted">${esc(e.status)}${e.rehearsal?' · Practice debate':''}</p>${button('Open event','open-event',`data-event="${esc(e.id)}"`)}</article>`).join(''):'<p>You have no events yet. Create a match or join with an invitation.</p>';
}
async function loadDiscovery(cursor){const result=await request('/debate-room/discover'+(cursor?'?cursor='+encodeURIComponent(cursor):''));const html=result.events.map(e=>`<article><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><p class="muted">${esc(e.timezone)} · ${esc(e.language)} · ${esc(e.status)}</p>${button('Request entry','join-public',`data-event="${esc(e.id)}"`)}</article>`).join('');if(cursor)$('discover-events').insertAdjacentHTML('beforeend',html);else $('discover-events').innerHTML=html||'<p>No open events are listed right now. You can still join with an invitation.</p>';$('discover-more').hidden=!result.nextCursor;$('discover-more').onclick=()=>guarded(()=>loadDiscovery(result.nextCursor));}
async function openEvent(eventId) {
  const view=state.viewGeneration,account=state.accountGeneration;await leaveCurrentMedia();if(view!==state.viewGeneration||account!==state.accountGeneration)return;clearSensitiveViews();$('context-change-note').hidden=true; state.judgeDirty=false;
  const result=await request(`/debate-room/snapshot?eventId=${encodeURIComponent(eventId)}`); state.event=null; adopt(result.event,true); status('Event opened.');
}
function openDialog(title,fields,onSubmit,submitLabel='Save') {
  $('dialog-title').textContent=title; $('dialog-fields').innerHTML=fields; $('dialog-status').textContent=''; $('dialog-submit').textContent=submitLabel;
  $('dialog-form').onsubmit=async event=>{event.preventDefault(); $('dialog-submit').disabled=true; try { await onSubmit(new FormData(event.currentTarget)); $('dialog').close(); }catch(error){$('dialog-status').textContent=publicErrorMessage(error.message);}finally{$('dialog-submit').disabled=false;}};
  if(!$('dialog').open)$('dialog').showModal();
}
function readValues(form) { return Object.fromEntries(form.entries()); }
function reasonDialog(title,action,extra={},reasonField='reason') { openDialog(title,'<label>Reason<textarea name="reason" required maxlength="2000" rows="3"></textarea></label>',form=>command(action,matchPayload({...extra,[reasonField]:form.get('reason')})),title); }

function renderPanel() {
  if(!state.event)return;
  document.querySelectorAll('#event-tabs button').forEach(b=>b.setAttribute('aria-current',b.dataset.panel===state.panel?'page':'false'));
  document.querySelectorAll('section.panel').forEach(panel=>panel.hidden=panel.id!==`panel-${state.panel}`);
  ({overview:renderOverview,participants:renderPeople,rules:renderRules,live:renderLive,judge:renderJudge,vote:renderVote,results:renderResults,schedule:renderSchedule,help:renderHelp})[state.panel]?.();
}
function renderOverview() {
  const event=state.event,m=currentMatch();
  if(event.awaitingAdmission){$('overview-content').innerHTML=`<h2>Waiting for the host</h2><p>${esc(event.description)}</p><p>Your entry request is saved. The host must admit you before you can see the event roster, motions, or live room.</p><p>${me()?.checkedIn?'Your arrival is confirmed.':'Use Check in to confirm your arrival.'}</p>`;return;}
  $('overview-content').innerHTML=`<div class="columns"><section><h2>Your event</h2><p>${esc(event.description || 'A three-speaker Modified Oxford–Oregon debate.')}</p><p>${esc(formatTime(event.scheduledAt))}</p>${event.contact?.name||event.contact?.email||event.contact?.url?`<p>Event contact: ${esc(event.contact.name)} ${event.contact.email?`<a href="mailto:${esc(encodeURIComponent(event.contact.email))}">${esc(event.contact.email)}</a>`:''} ${event.contact.url?`<a href="${esc(event.contact.url)}" target="_blank" rel="noopener noreferrer">Contact website</a>`:''}</p>`:''}<p>${esc(me()?.checkedIn?'You are checked in.':'Check in when you arrive.')}${me()?.admitted?'':' Admission is awaiting the host.'}</p><div class="actions">${host()?button('Edit event','edit-event')+button('Create invitation','invite')+button('Add team','team')+button('Add motion','motion')+button('Set up match','match','', 'primary'):''}${button('Retry last action','retry')}</div></section><section><h2>${m&&m.phase!=='setup'?'Match in progress':'Ready to begin'}</h2>${m?`<p>${esc(m.title)} · ${esc(m.phase)}</p><ul>${(m.readiness?.issues || m.readiness?.reasons || []).map(issue=>`<li>${esc(typeof issue==='string'?issue:issue.message)}</li>`).join('')}</ul><p>${m.readiness?.ready?'All required readiness checks are confirmed.':'Complete roster, check-in, neutral officials, microphone checks, motion and captain acknowledgments.'}</p><div class="actions">${button('Record my microphone check','device-check')}${host()&&m.phase==='setup'?button('Start match','start-match','', 'primary'):button('Open live room','select-match',`data-match="${esc(m.id)}"`)}</div>`:'<p>Add two confirmed teams, a motion and at least one neutral judge, then set up the match.</p>'}</section></div>${m?checkInSummary(m):''}<hr><h2>Organizer journey</h2><ol class="steps"><li>Create the event and invite participants.</li><li>Confirm teams, judges, sides, rules and readiness.</li><li>Release the motion and prepare privately.</li><li>Run every stage with the shared timer and assigned floor.</li><li>Complete adjudication, publish the provisional result and resolve corrections.</li><li>Finalize, export results and move to the next match.</li></ol>`;
}
function checkInSummary(m){const c=m.checkIn;if(!c)return '';return `<hr><h2>Match check-in</h2><p>Scheduled: ${esc(formatTime(c.scheduledAt))}. Grace: ${c.graceMs/60000} minutes${c.deadlineAt?' · until '+esc(formatTime(c.deadlineAt)):''}.</p><p>${esc(humanState(c.state))}. A missed check-in requires a human ruling; it never creates an automatic forfeit. A participant who checked in and later disconnected is not a no-show.</p><p>${c.attendance?.[state.event.myId]?'Your arrival for this match is recorded.':'Use Check in to record your arrival for this match.'}</p>${moderationOfficial()&&m.phase==='setup'?`<div class="actions">${!m.rulesLockedAt?button('Set check-in time','schedule-check-in'):''}${c.state==='GRACE_ELAPSED'?button('Record absent participant','record-no-show'):''}</div>`:''}${(c.findings||[]).map(f=>`<p>${esc(personName(f.memberId))} · ${esc(humanState(f.status))}: ${esc(f.reason)}</p>`).join('')}`;}

function renderPeople() {
  $('participants-content').innerHTML=`<div class="section-heading"><h2>People</h2><div class="actions">${button('Check-in and conflict declaration','declare-conflicts')}${host()?button('Create invitation','invite')+button('Confirm team','team'):''}</div></div><div class="table-scroll"><table><thead><tr><th>Participant</th><th>Event roles</th><th>Arrival</th><th>Controls</th></tr></thead><tbody>${state.event.members.map(p=>`<tr><td>${esc(p.displayName)}${p.conflictDeclarations?.length?`<ul>${p.conflictDeclarations.map(note=>`<li>Declared conflict: ${esc(note)}</li>`).join('')}</ul>`:''}</td><td>${esc(p.roles.join(', '))}</td><td>${p.removed?'Removed':!p.admitted?'Waiting for admission':p.checkedIn?'Checked in':'Invited'}</td><td>${host()?`${!p.admitted?button('Admit','admit',`data-person="${esc(p.id)}"`):''}${button('Roles','roles',`data-person="${esc(p.id)}"`)}`:''}${p.id!==state.event.myId?button(state.mutedPeople.has(p.id)?'Unmute for me':'Mute for me','mute-person',`data-person="${esc(p.id)}"`)+button(state.blockedPeople.has(p.id)?'Unblock for me':'Block for me','block-person',`data-person="${esc(p.id)}"`):''}${host()&&p.id!==state.event.ownerId?button(p.removed?'Reinstate':'Remove',p.removed?'reinstate-person':'remove-person',`data-person="${esc(p.id)}"`):''}${moderationOfficial()?button('End extra floor','revoke-floor',`data-person="${esc(p.id)}"`)+button('Grant microphone','grant-floor',`data-person="${esc(p.id)}"`)+button('Presenter','presenter',`data-person="${esc(p.id)}"`):''}</td></tr>`).join('')}</tbody></table></div><hr><p>Personal mute and block affect only your device. They do not remove a participant or change the official floor.</p>${moderationOfficial()?button(currentMatch().quietObservers?'Allow observer chat':'Quiet observer chat','quiet-observers'):''}<h2>Teams</h2><div class="columns">${state.event.teams.map(t=>`<section><h3>${esc(t.name)}</h3><p>${esc(t.school)}</p><ol>${t.speakerIds.map(p=>`<li>${esc(personName(p))}${p===t.captainId?' · Captain':''}</li>`).join('')}</ol>${t.proposal?`<p>Proposed roster: ${t.proposal.speakerIds.map(personName).map(esc).join(', ')}. Captain: ${esc(personName(t.proposal.captainId))}. Awaiting organizer confirmation.</p>`:''}${host()?button(t.proposal?'Review proposed team':'Edit team','team',`data-team="${esc(t.id)}"`):t.captainId===state.event.myId?button('Propose roster','team',`data-team="${esc(t.id)}"`):''}</section>`).join('')}</div>${host()?`<hr><h2>Invitations</h2><p class="muted">Privileged invitations require verified identity or explicit host approval. Invitations do not grant a judging ballot by themselves.</p>${state.event.invites.map(i=>`<p>${esc(i.role)} · ${i.revokedAt?'Revoked':`Expires ${esc(formatTime(i.expiresAt))}`} ${!i.revokedAt?button('Revoke','revoke-invite',`data-invite="${esc(i.id)}"`):''}</p>`).join('')}`:''}`;
}
function renderRules() {
  const m=currentMatch();
  $('rules-content').innerHTML=`<div class="section-heading"><h2>Rules &amp; motion</h2><div class="actions">${host()?button('Add motion','motion')+(m?button('Edit rules','edit-rules'):''):''}</div></div>${m?`<p>${esc(m.rules.preset)} · Version ${m.ruleVersion} · ${m.rulesLockedAt?'Locked for this match':'Open for confirmation'}</p><p>Constructive ${m.rules.constructiveMs/60000} minutes · Interpellation ${m.rules.interpellationMs/60000} minutes · Closing ${m.rules.rebuttalMs/60000} minutes</p><p>Official decision: ${esc(m.rules.judgingMode)}. Audience Choice is separate.</p><div class="actions">${button('Accept these rules and sides','acknowledge')}${host()?button('Release motion','release-motion')+button('Random side draw','draw-sides'):''}${button('Download rules PDF','export', 'data-kind="rules"')}</div>`:''}<hr><div>${state.event.motions.map(motion=>`<article><h3>${esc(motion.title)}</h3><p>${esc(motion.text)}</p><p class="muted">${motion.releasedAt?'Released to participants':'Private to the organizer until release'}</p></article>`).join('') || '<p>The motion has not been released to you.</p>'}</div>${m?sanctionSummary(m):''}<hr>${rulebook()}`;
}
function sanctionSummary(m){const policy=m.rules.sanctions||[],records=m.sanctions||[],reversed=new Set(records.filter(r=>r.action==='reverse').map(r=>r.recordId));const canRecord=moderationOfficial()&&m.rulesLockedAt&&['preparation','live','break','deliberation'].includes(m.phase)&&!m.resultVersions.some(r=>['PROVISIONAL_PUBLISHED','FINAL'].includes(r.state));return `<hr><h2>Declared sanctions</h2><p>No penalty is automatic, including overtime. Officials must record a reason. Fixed team point deductions require aggregate judging, are shown separately from raw scores, and do not change raw speech awards.</p>${!m.rulesLockedAt&&host()?button('Add declared sanction','edit-sanction-policy'):''}${policy.length?policy.map(p=>`<article><h3>${esc(p.label)}</h3><p>${esc(p.description)}</p><p>${p.effect==='warning'?'Warning without point deduction':'Fixed team deduction: '+esc(p.points)+' points'}</p>${!m.rulesLockedAt&&host()?button('Edit declaration','edit-sanction-policy',`data-sanction="${esc(p.id)}"`)+button('Remove declaration','remove-sanction-policy',`data-sanction="${esc(p.id)}"`):''}</article>`).join(''):'<p>No custom sanctions declared.</p>'}${canRecord&&policy.length?button('Record declared sanction','record-sanction'):''}<h3>Manual sanction record</h3>${records.map(r=>`<article><p>${r.action==='reverse'?'Reversal of '+esc(r.recordId):esc(r.label)+' · '+esc(r.target.side?sideName(r.target.side):r.target.seat+' · '+personName(m.seats[r.target.seat]))}${r.pointsHundredths?' · '+(r.pointsHundredths/100).toFixed(2)+' points':''} · ${esc(formatTime(r.at))}</p><p>${esc(r.reason)} · ${esc(personName(r.actorId))}</p>${r.action==='issue'&&reversed.has(r.id)?'<p>Reversed; original record retained.</p>':r.action==='issue'&&canRecord?button('Reverse with reason','reverse-sanction',`data-record="${esc(r.id)}"`):''}</article>`).join('')||'<p>No sanctions recorded.</p>'}`;}
function sanctionPolicyDialog(sanctionId){const m=currentMatch(),policy=m.rules.sanctions||[],prior=policy.find(p=>p.id===sanctionId);openDialog(prior?'Edit declared sanction':'Declare a custom sanction',`<p>Declare conditions before the match starts. Default: no custom sanctions. Point deductions require aggregate judging; majority and simple ballots permit warnings.</p>${field('Label','label',prior?.label||'')}<label>Conditions<textarea name="description" required maxlength="2000">${esc(prior?.description||'')}</textarea></label><label>Effect<select name="effect">${option('warning','Warning without point deduction',prior?.effect)}${m.rules.judgingMode==='aggregate'?option('team_point_deduction','Fixed team point deduction',prior?.effect):''}</select></label>${field('Fixed deduction points (used only for point deduction)','points',prior?.points||'1.00','number','min="0.01" max="100" step="0.01"')}`,form=>{const declaration={id:prior?.id||id(),label:form.get('label'),description:form.get('description'),effect:form.get('effect'),...(form.get('effect')==='team_point_deduction'?{points:form.get('points')}:{})};return command('update_rules',matchPayload({rules:{...copy(m.rules),sanctions:[...policy.filter(p=>p.id!==prior?.id),declaration]}}));},'Save declaration');}
function recordSanctionDialog(){const m=currentMatch();openDialog('Record a declared sanction',`<p>This is a human ruling. Raw scorecards remain unchanged. A point deduction must target a team; a warning may target a team or speaking seat.</p><label>Declared sanction<select name="sanctionId">${m.rules.sanctions.map(p=>option(p.id,p.label+(p.effect==='team_point_deduction'?' — '+p.points+' points':''))).join('')}</select></label><label>Target<select name="target">${['affirmative','negative'].map(side=>option(side,sideName(side))).join('')}${SEATS.map(seat=>option(seat,seat+' · '+personName(m.seats[seat])+' (warning only)')).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label><label class="inline"><input type="checkbox" required>I confirm this disclosed ruling</label>`,form=>command('record_sanction',matchPayload({action:'issue',sanctionId:form.get('sanctionId'),target:SEATS.includes(form.get('target'))?{seat:form.get('target')}:{side:form.get('target')},reason:form.get('reason'),confirmed:true})),'Record sanction');}
function resultAdjustmentSummary(result){if(!result.sanctions?.length)return '';return `<h3>Disclosed adjustments</h3><p>Raw scorecards and speech awards remain unchanged.${result.application==='not_applied_exceptional_conclusion'?' Sanctions are recorded but not applied to this exceptional conclusion.':''}</p>${result.adjustedTeamScores?`<div class="table-scroll"><table><thead><tr><th>Team</th><th>Raw panel score</th><th>Adjusted official score</th></tr></thead><tbody>${['affirmative','negative'].map(side=>`<tr><td>${sideName(side)}</td><td>${esc(result.rawTally?.teamScores?.[side]?.display)}</td><td>${esc(result.adjustedTeamScores[side]?.display)}</td></tr>`).join('')}</tbody></table></div>`:''}<ul>${(result.adjustments||[]).map(r=>`<li>${esc(r.label)} · ${esc(r.target.side?sideName(r.target.side):r.target.seat)}${r.pointsHundredths?' · -'+(r.pointsHundredths/100).toFixed(2)+' points':''}: ${esc(r.reason)}</li>`).join('')||'<li>No active numerical adjustments.</li>'}</ul>`;}

function rulebook() {
  return `<h2>The 5/3/5 preset</h2><p>Each team has exactly three active speakers. The captain is one of those three; any assigned team speaker may deliver its closing.</p><p>Six alternating constructives take five minutes each. Each is followed by three minutes of questioning and answering with both assigned participants on the floor. After the optional five-minute private break, Negative closes, then Affirmative closes, five minutes each.</p><p>The timer starts only when its controller acts. At zero it counts overtime in red. Time alone does not mute, end a speech, penalize a team or decide a winner.</p><p>Default team score: average of the three individual subtotals (up to 85), plus one closing score (up to 15). Full scorecards use majority judge ballots unless aggregate scoring was selected before rules lock. Private drafts stay private.</p><p>Both captains accept the same rules. A neutral moderator handles objections, technical pauses and accommodations. No software decision replaces human judging. During questioning, new team messages to the active pair are blocked; previously received notes remain available.</p><p>This is the Due Diligence Modified Oxford–Oregon preset, not a universal national rulebook.</p><p class="muted">Source notes: <a href="https://www.recoletosdebaguio.edu.ph/2022/04/06/cares-holds-philosophical-debate-during-jornadas-de-filosofia-2022/" target="_blank" rel="noopener noreferrer">Casiciaco Recoletos Seminary</a>; <a href="https://ourhappyschool.com/debate/debate-tournament-framework-mechanics-guidelines-etc" target="_blank" rel="noopener noreferrer">Mañebog’s tournament framework</a>; <a href="https://catanduanes.deped.gov.ph/files/UM---Inter-Schools-Debate-for-the-Environment-and-Battle-of-Best-Partnership-Initiatives-and-Awarding-Ceremonies.pdf" target="_blank" rel="noopener noreferrer">DENR/DepEd event mechanics</a>. Timing, order and weights vary by event.</p>`;
}

function ensureTile(key,label,parent,identity,seat) {
  let tile=state.tiles.get(key);
  if(!tile){tile=document.createElement('article');tile.className='tile';tile.innerHTML='<span class="initials" aria-hidden="true"></span><div class="caption"><span></span><small>Camera off</small></div>';state.tiles.set(key,tile);}
  if(tile.dataset.identity!==String(identity||''))for(const video of tile.querySelectorAll('video'))video.remove();
  tile.dataset.identity=identity || ''; tile.dataset.seat=seat || '';
  tile.classList.toggle('pinned',state.pinnedTile===key);
  let pin=tile.querySelector('.tile-pin');if(!pin){pin=document.createElement('button');pin.type='button';pin.className='tile-pin';pin.onclick=()=>{state.pinnedTile=state.pinnedTile===key?null:key;renderLive();};tile.append(pin);}pin.textContent=state.pinnedTile===key?'Unpin':'Pin';pin.setAttribute('aria-label',(state.pinnedTile===key?'Unpin ':'Pin ')+label);pin.setAttribute('aria-pressed',String(state.pinnedTile===key));
  tile.querySelector('.caption span').textContent=label;
  tile.querySelector('.initials').textContent=label.split(/\s+/).slice(0,2).map(x=>x[0]).join('');
  if(tile.parentElement!==parent)parent.append(tile);
  const existing=[...media.videos.values()].find(v=>v.identity===identity && v.source==='camera');
  if(existing && existing.element.parentElement!==tile)tile.prepend(existing.element);
  return tile;
}
function renderLive() {
  const m=currentMatch(); if(!m){$('live-motion').textContent='No active match record is available.';$('stage-controls').replaceChildren();$('active-match').replaceChildren();for(const tile of state.tiles.values())tile.remove();state.tiles.clear();return;}
  const matches=usableMatches();
  const chosen=$('active-match').value;
  if($('active-match').options.length!==matches.length || !matches.some(x=>x.id===chosen))$('active-match').innerHTML=matches.map(x=>option(x.id,x.title,m.id)).join('');
  $('active-match').value=m.id;
  $('live-motion').textContent=state.event.motions.find(x=>x.id===m.motionId)?.text || 'Awaiting motion release';
  $('affirmative-name').textContent=state.event.teams.find(t=>t.id===m.teamIds?.affirmative)?.name || 'Affirmative';
  $('negative-name').textContent=state.event.teams.find(t=>t.id===m.teamIds?.negative)?.name || 'Negative';
  const stage=m.runOfShow?.[m.currentStageIndex]; const floorSeats=stage?.speakerSeats || [];
  for(const seat of SEATS){const user=m.seats[seat];const tile=ensureTile(seat,`${seat} · ${personName(user)}`,seat[0]==='A'?$('affirmative-tiles'):$('negative-tiles'),mediaIdentity(user),seat);tile.classList.toggle('on-floor',floorSeats.includes(seat));}
  const judgeKeys=new Set(m.judgeIds.map(x=>`judge-${x}`));
  for(const key of [...state.tiles.keys()])if(key.startsWith('judge-')&&!judgeKeys.has(key)){state.tiles.get(key).remove();state.tiles.delete(key);}
  for(const user of m.judgeIds)ensureTile(`judge-${user}`,`${personName(user)}${m.chiefId===user?' · Chief':''}`,$('judge-tiles'),mediaIdentity(user));
  const observers=state.event.members.filter(p=>p.admitted&&!p.removed&&!Object.values(m.seats).includes(p.id)&&!m.judgeIds.includes(p.id));
  const page=observers.slice(state.observerPage*6,state.observerPage*6+6);const pageKeys=new Set(page.map(p=>`observer-${p.id}`));
  for(const key of [...state.tiles.keys()])if(key.startsWith('observer-')&&!pageKeys.has(key)){state.tiles.get(key).remove();state.tiles.delete(key);}
  for(const user of page)ensureTile(`observer-${user.id}`,user.displayName,$('observer-tiles'),mediaIdentity(user.id));
  media.setVideoSubscriptions?.({priority:[...Object.values(m.seats),...m.judgeIds].map(mediaIdentity).filter(Boolean),visible:page.map(p=>mediaIdentity(p.id)).filter(Boolean)});
  $('observers-prev').disabled=state.observerPage===0;$('observers-next').disabled=(state.observerPage+1)*6>=observers.length;
  $('stage-label').textContent=stage?.label || stage?.kind || m.phase;
  $('speaker-label').textContent=floorSeats.length?floorSeats.map(seat=>`${seat} · ${personName(m.seats[seat])}`).join(' ↔ '):m.phase==='setup'?'Complete readiness to begin':'Private preparation / deliberation';
  const next=m.runOfShow?.[m.currentStageIndex+1];$('next-stage').textContent=next?`Next: ${next.label || next.kind}`:'No next speaking stage';
  $('run-of-show').innerHTML=(m.runOfShow || []).map((s,i)=>`<li class="${i===m.currentStageIndex?'current':''}">${esc(s.label || `${s.id} ${s.kind}`)} · ${s.durationMs == null?'Untimed':`${s.durationMs/60000} min`}</li>`).join('');
  const controlsKey=JSON.stringify([m.id,m.currentStageIndex,m.timer?.state,official()]);if($('stage-controls').dataset.renderKey!==controlsKey){$('stage-controls').dataset.renderKey=controlsKey;$('stage-controls').innerHTML=!m.timer?(moderationOfficial()&&m.phase==='setup'?button('Start match','start-match'): '<p>No active speech clock. Continue on the Judge or Results tab when the speaking phase is complete.</p>'):official()?`${button('Take timer control','claim-clock')}${m.timer?button('Start','timer','data-type="START"')+button(m.timer.state==='PAUSED'?'Resume':'Pause','timer',`data-type="${m.timer.state==='PAUSED'?'RESUME':'PAUSE'}"`)+button('Finish stage','timer','data-type="FINISH"')+button('Next stage','next-stage')+button('Return to stage','return-stage')+button('Technical pause','technical-pause')+button('Reset timer','reset-clock')+button('Change duration','edit-clock'):''}`:'';}
  $('private-space-controls').innerHTML=['main','affirmative','negative','judges'].map(space=>button(space==='main'?'Main room':space==='judges'?'Judge deliberation':`${sideName(space)} preparation`,'space',`data-space="${space}"`)).join('')+['affirmative','negative','judges'].filter(space=>space==='judges'?m.phase==='deliberation'&&m.judgeIds.includes(state.event.myId):['preparation','break'].includes(m.phase)&&m.captains?.[space]===state.event.myId).map(space=>button('Invite moderator to '+(space==='judges'?'judges':sideName(space)),'invite-private',`data-space="${space}"`)).join('')+(m.privateRoomInvitations||[]).map(invite=>`<p>${esc(personName(invite.moderatorId))} · ${esc(humanState(invite.space))} · ${esc(humanState(invite.status))} · ${esc(invite.reason)} ${invite.status==='ACTIVE'&&(host()||invite.moderatorId===state.event.myId||invite.space==='judges'&&m.judgeIds.includes(state.event.myId)||m.captains?.[invite.space]===state.event.myId)?button('Revoke invitation','revoke-private',`data-invitation="${esc(invite.id)}"`):''}</p>`).join('');
  if(state.lastStage!==stage?.id){state.lastStage=stage?.id;$('stage-announcement').textContent=`${$('stage-label').textContent}. ${$('speaker-label').textContent}`;}
  renderMessages();applyPersonalAudio();
  $('evidence-list').innerHTML=(m.evidence || []).map(e=>`<article><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p>${e.attachment?button('Download evidence','evidence-download',`data-evidence="${esc(e.id)}"`):''}${/^https?:\/\//i.test(e.url || e.sourceUrl || '')?`<a href="${esc(e.url || e.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}<small> · Version ${e.version || 1}</small></article>`).join('')||'<p class="muted">No shared evidence yet.</p>';
  updateClock();
}
function renderMessages(){const m=currentMatch();const channel=$('channel').value;const actual=channel==='team'?('team:'+(myTeamSide()||'unassigned')):channel==='main'?'public':channel;
  const key=messageHistoryKey(actual);const byId=new Map([...(state.messageHistory.get(key)||[]),...(m?.messages||[])].map(message=>[message.id,message]));
  $('load-older').disabled=state.historyDone.has(key);$('load-older').textContent=state.historyDone.has(key)?'Beginning of available history':'Load older messages';
  $('messages').innerHTML=[...byId.values()].sort((a,b)=>(a.at||a.createdAt)-(b.at||b.createdAt)).filter(x=>x.channel===actual&&!state.blockedPeople.has(x.actorId||x.senderId)).map(message=>`<li><strong>${esc(personName(message.actorId || message.senderId))}</strong><time>${esc(formatTime(message.createdAt || message.at))}</time><p>${esc(message.text)}</p></li>`).join('');
  $('channel-policy').textContent=actual==='public'?'Visible to admitted participants.':actual==='judges'?'Assigned judges only.':'Private team channel. Active questioning participants cannot receive new team messages.';
}
function messageHistoryKey(channel){return [state.event?.id,currentMatch()?.id,channel].join(':');}
async function loadHistory(){const view=state.viewGeneration;const choice=$('channel').value,channel=choice==='main'?'public':choice==='team'?'team:'+(myTeamSide()||'unassigned'):choice,key=messageHistoryKey(channel);const current=[...(state.messageHistory.get(key)||[]),...(currentMatch()?.messages||[])].filter(m=>m.channel===channel).sort((a,b)=>(a.at||a.createdAt)-(b.at||b.createdAt));const params=new URLSearchParams({eventId:state.event.id,matchId:currentMatch().id,channel,limit:'50'});if(current[0]?.id)params.set('before',current[0].id);const result=await request('/debate-room/messages?'+params);if(view!==state.viewGeneration||key!==messageHistoryKey(channel))return;state.messageHistory.set(key,[...(state.messageHistory.get(key)||[]),...result.messages]);if(!result.nextCursor)state.historyDone.add(key);renderMessages();}
function personalKey(){return 'duediligence.debate.personal.v3.'+state.session?.user?.id;}
function loadPersonal(){try{const value=JSON.parse(localStorage.getItem(personalKey())||'{}');state.mutedPeople=new Set((value.muted||[]).slice(0,500));state.blockedPeople=new Set((value.blocked||[]).slice(0,500));}catch{state.mutedPeople=new Set();state.blockedPeople=new Set();}}
function applyPersonalAudio(){for(const track of media.audioTracks.values()){const account=currentMatch()?.mediaParticipants?.find(p=>p.identity===track.identity)?.userId;track.element.muted=!account||state.mutedPeople.has(account)||state.blockedPeople.has(account);}}
function savePersonal(){try{localStorage.setItem(personalKey(),JSON.stringify({muted:[...state.mutedPeople].slice(0,500),blocked:[...state.blockedPeople].slice(0,500)}));}catch{status('This device cannot save your personal mute preferences. They apply until you leave.');}applyPersonalAudio();renderMessages();renderPeople();}
function updateClock(){const m=currentMatch();if(!m?.timer){$('clock').textContent='Ready';return;}const now=serverNow(),stale=!state.sync||performance.now()-state.sync.local>15000||navigator.onLine===false;for(const b of $('stage-controls').querySelectorAll('button'))b.disabled=stale||['timer','reset-clock','edit-clock'].includes(b.dataset.action)&&(m.timer.controllerId!==state.event.myId||m.timer.leaseExpiresAtServerMs<=now);const display=timerDisplay(m.timer,now);$('clock').textContent=display.text;$('clock').classList.toggle('overtime',display.overtime);$('clock-status').textContent=`${m.timer.state}${!state.sync||performance.now()-state.sync.local>15000?' · Stale — reconnecting':''}`;}

function renderJudge() {
  const m=currentMatch();if(!m){$('judge-content').innerHTML='<p>Create or select a match first.</p>';return;}
  if(!m.judgeIds.includes(state.event.myId)){$('judge-content').innerHTML=`<h2>Adjudication</h2><p>Only an assigned eligible judge can open their private scorecard.</p><p>${m.ballotCompletion.received} of ${m.ballotCompletion.required} final ballots received. Preferences remain private.</p>${panelAdmin()?`<div class="actions">${button('Open final ballots','open-ballots')}${button('Close ballots','close-ballots')}${button('Panel change / recusal','panel-change')}</div>`:''}`;return;}
  if(state.judgeDirty)return;
  const draft=(['CLOSED','FINAL'].includes(m.ballotState)?m.myBallot:m.myDraft) || m.myDraft || m.myBallot || {};const card=decimalCard(draft.scorecard || {speakers:{},closing:{}});
  $('judge-content').innerHTML=`<div class="section-heading"><h2>My private scorecard</h2><p id="draft-status" role="status">${draft.savedAt?'Saved draft restored':'No saved draft yet'}</p></div><p>Scoring mode: ${esc(m.rules.judgingMode)}. Blanks are incomplete; an explicit zero is a score. Your private notes are not shared with the organizer or other judges.</p><form id="score-form">${m.rules.judgingMode==='simple'?`<label>Winner<select name="winner"><option value="">Choose a side</option>${['affirmative','negative'].map(s=>option(s,sideName(s),draft.winner)).join('')}</select></label>`:`<div class="table-scroll"><table><thead><tr><th>Speaker</th>${SPEAKER_CRITERIA.map(k=>`<th>${esc(m.rules.rubric.labels[k])}<br>0–${m.rules.rubric.weights[k]}</th>`).join('')}</tr></thead><tbody>${SEATS.map(seat=>`<tr><td>${seat}<br>${esc(personName(m.seats[seat]))}</td>${SPEAKER_CRITERIA.map(k=>`<td><input aria-label="${esc(`${seat} ${m.rules.rubric.labels[k]}`)}" name="${seat}.${k}" type="number" min="0" max="${m.rules.rubric.weights[k]}" step="0.01" value="${esc(card.speakers?.[seat]?.[k] ?? '')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="columns">${['affirmative','negative'].map(s=>field(`${sideName(s)} closing — ${personName(m.seats[m.closingSeats[s]])}`,`closing.${s}`,card.closing?.[s] ?? '', 'number',`min="0" max="${m.rules.rubric.weights.closing}" step="0.01"`)).join('')}</div><p id="score-preview" class="score-total"></p><label>Choice if exact scores are tied<select name="tieBreakChoice"><option value="">Only needed for an exact tied scorecard</option>${['affirmative','negative'].map(s=>option(s,sideName(s),card.tieBreakSide)).join('')}</select></label>`}<label>Reasoned decision / tie explanation<textarea name="reason" maxlength="4000" rows="3">${esc(draft.reason || card.tieBreakReason || '')}</textarea></label>${['affirmative','negative'].map(side=>`<label>Feedback for ${sideName(side)} (shared only if the official releases it)<textarea name="feedback.${side}" maxlength="4000" rows="3">${esc(draft.feedback?.[side] || '')}</textarea></label>`).join('')}<label>Private notes<textarea name="notes" maxlength="12000" rows="5">${esc(draft.notes || '')}</textarea></label><div class="actions"><button type="submit" class="primary">Save private draft</button>${button('Review and submit final ballot','submit-ballot')}${button('My scorecard PDF','export','data-kind="scorecard"')}${button(['RUNOFF_REQUIRED','AWAITING_RUNOFF'].includes(m.nominationStatus?.status)?'Complete Best Debater runoff':'Nominate Best Debater','nominate')}</div></form><p>Final ballots: ${esc(m.ballotState)} · ${m.ballotCompletion.received}/${m.ballotCompletion.required} received.</p>${panelAdmin()?`<div class="actions">${button('Open final ballots','open-ballots')}${button('Close ballots','close-ballots')}${button('Panel change / recusal','panel-change')}</div>`:''}`;
  $('score-form').addEventListener('input',()=>{state.judgeDirty=true;$('draft-status').textContent='Unsaved changes';previewScore();});
  $('score-form').addEventListener('focusout',()=>{clearTimeout(state.draftTimer);state.draftTimer=setTimeout(()=>{if(state.judgeDirty&&!state.busy)saveDraft().catch(()=>{});},650);});
  $('score-form').onsubmit=async event=>{event.preventDefault();await guarded(saveDraft);};if(m.ballotState==='FINAL')for(const control of $('score-form').querySelectorAll('input,textarea,select,button[type=submit],[data-action=submit-ballot],[data-action=nominate]'))control.disabled=true;previewScore();
}
function decimalCard(value){const card=copy(value);if(card.encoding==='hundredths'){for(const scores of Object.values(card.speakers||{}))for(const key of Object.keys(scores))if(scores[key]!=null)scores[key]=scores[key]/100;for(const key of Object.keys(card.closing||{}))if(card.closing[key]!=null)card.closing[key]=card.closing[key]/100;card.encoding='decimal';}return card;}
function scoreFormData(){const form=$('score-form');if(!form)return {};const values=new FormData(form);const card={speakers:Object.fromEntries(SEATS.map(seat=>[seat,Object.fromEntries(SPEAKER_CRITERIA.map(k=>[k,values.get(`${seat}.${k}`) || null]))])),closing:Object.fromEntries(['affirmative','negative'].map(s=>[s,values.get(`closing.${s}`)||null]))};card.tieBreakSide=values.get('tieBreakChoice')||null;card.tieBreakReason=card.tieBreakSide?values.get('reason')||null:null;return {scorecard:currentMatch().rules.judgingMode==='simple'?null:card,winner:values.get('winner')||null,reason:values.get('reason'),notes:values.get('notes'),feedback:{affirmative:values.get('feedback.affirmative'),negative:values.get('feedback.negative')}};}
function previewScore(){if(!$('score-preview'))return;try{const result=scoreScorecard(scoreFormData().scorecard,currentMatch().rules);$('score-preview').textContent=`Affirmative ${result.affirmative?.display || result.teams?.affirmative?.display || 'Complete'} · Negative ${result.negative?.display || result.teams?.negative?.display || 'Complete'}`;}catch{$('score-preview').textContent='Complete every score to calculate team totals.';}}
async function saveDraft(){const view=state.viewGeneration,payload=scoreFormData();const result=await command('save_draft',matchPayload(payload));if(view!==state.viewGeneration)return result;state.judgeDirty=false;if($('draft-status'))$('draft-status').textContent='Saved';return result;}

function audienceSummary(p){if(!p?.published)return '<p>No published Audience Choice result is available.</p>';return `<p class="result-winner">${esc(p.status==='NO_VOTES'?'No valid votes':p.status==='TIE'?'Audience tie':sideName(p.winner))}</p><div class="columns">${['affirmative','negative'].map(side=>`<p><strong>${sideName(side)}</strong><br>${p.counts[side]} votes${p.choicePercentages[side]==null?'':` · ${p.choicePercentages[side]}%`}</p>`).join('')}</div><p>Turnout: ${p.validVotes} of ${p.eligibleCount} eligible observers${p.turnoutPercent==null?'':` (${p.turnoutPercent}%)`}. Invalidated votes: ${p.invalidatedCount}.</p>`;}
function renderVote(){const m=currentMatch(),p=m?.poll;if(!m){$('vote-content').innerHTML='<p>Select a match first.</p>';return;}$('vote-content').innerHTML=`<h2>Audience Choice</h2><p>Audience Choice is separate from official judging, awards and bracket progression. Every eligible observer has one current vote.</p>${!p?'<p>The host has not opened a poll.</p>':`<p>Poll: ${esc(p.state)}</p>${p.state==='Open'&&p.eligible?`<p>Your current choice: ${esc(p.myVote?sideName(p.myVote):'No vote')}</p><div class="actions">${button('Affirmative','vote','data-side="affirmative"')}${button('Negative','vote','data-side="negative"')}${button('Withdraw vote','withdraw-vote')}</div>`:p.state==='Open'?'<p>You are not in this poll’s list of eligible observers.</p>':''}${p.result?audienceSummary(p.result):'<p>Totals remain private until the poll is closed and published.</p>'}`}${moderationOfficial()?`<hr><div class="actions">${button('Open poll','open-poll')}${button('Close poll','close-poll')}${button('Publish Audience Choice','publish-poll')}</div>`:''}`;}
function awardsSummary(summary,tournament=false){if(!summary)return '<p>Awards await finalization.</p>';return `${summary.reason?`<p>${esc(summary.reason)}</p>`:''}<div class="columns">${Object.entries(awardNames).filter(([key])=>summary[key]).map(([key,title])=>{const award=summary[key];const names=award.winnerParticipants?.map(p=>p.displayName)||(award.winners||[]).map(x=>tournament?personName(x):`${x} · ${personName(currentMatch().seats[x])}`);return `<section><h4>${title}</h4><p><strong>${esc(names.length?names.join('; '):humanState(award.status))}</strong></p>${award.status==='COAWARD'?'<p>Shared award</p>':''}<p>${esc(award.reason||award.definition||'Reasoned nomination by eligible judges.')}</p>${tournament?`<details><summary>Eligibility and completed performances</summary><ul>${(award.eligibility||[]).map(p=>`<li>${esc(p.displayName)}: ${p.matchCount} · ${p.eligible?'Eligible':esc(p.reason)}</li>`).join('')}</ul></details>`:''}</section>`;}).join('')}</div>`;}
function renderResults(){const m=currentMatch();if(!m){$('results-content').innerHTML='<p>Select a match first.</p>';return;}const result=m.resultVersions.filter(r=>r.state!=='SUPERSEDED').at(-1);
  $('results-content').innerHTML=`<h2>Official result</h2>${result?`<p>${esc(humanState(result.state))} · Result version ${result.version || result.revision}</p><div class="result-winner">${esc(result.winner?sideName(result.winner):result.tabulation?.winner?sideName(result.tabulation.winner):'Unresolved')}</div><p>Decision method: ${esc(m.rules.judgingMode)}</p><div id="result-summary"></div>${resultAdjustmentSummary(result)}<h3>Awards</h3><div id="awards-summary"></div><p>Audience Choice is reported separately on the Vote tab.</p><div class="actions">${button('Download result PDF','export','data-kind="result"')}${button('Download results spreadsheet (CSV)','export','data-kind="csv"')}${button('Report a procedural error','protest')}${host()?button('Send results','send-results')+button('Issue certificate','export','data-kind="certificate"'):''}</div>`:'<p>Results have not been published. Final ballots must be complete before tabulation.</p>'}${panelAdmin()?`<hr><div class="actions">${button('Publish provisional result','publish-result')}${button('Finalize result','finalize-result')}${button('Correct result','correct-result')}${button('Reconsider tied result','reconsider')}</div>`:''}<hr><h3>Procedural reports</h3>${m.protests.map(p=>`<article><p>${esc(p.reason)} · ${esc(p.status || p.state)}</p>${panelAdmin()?button('Resolve report','resolve-protest',`data-protest="${esc(p.id)}"`):''}</article>`).join('')||'<p>No visible procedural reports.</p>'}<h3>Downloads and email delivery</h3>${state.event.outbox.map(j=>`<p>${esc(deliveryName(j.type))}${j.recipientLabel?' · '+esc(j.recipientLabel):''} · ${esc(humanState(j.status))}${j.error?` · ${esc(publicErrorMessage(j.error))}`:''} ${j.downloadId?button('Download','download',`data-download="${esc(j.downloadId)}"`):''}${j.type!=='media'&&j.status==='failed'?button('Retry','retry-job',`data-job="${esc(j.id)}"`):''}${['export','mail','invitation_mail'].includes(j.type)&&['failed','queued'].includes(j.status)?button('Cancel','cancel-job',`data-job="${esc(j.id)}"`):''}</p>`).join('')||'<p>No downloads or email deliveries requested yet.</p>'}`;
  if(result){$('result-summary').innerHTML=`<p>${esc(humanState(result.status))}</p><div class="columns">${['affirmative','negative'].map(side=>`<section><h3>${sideName(side)}</h3><p>${result.ballotSplit?.[side]??'No numeric'} ballots</p><p>Panel average: ${esc(result.teamScores?.[side]?.display??'Unavailable')}</p></section>`).join('')}</div>${result.state!=='FINAL'?`<p>Correction deadline: ${esc(formatTime(result.correctionDeadline))}</p>`:''}`;$('awards-summary').innerHTML=awardsSummary(result.awards);if(result.feedback&&Object.values(result.feedback).some(list=>list.length))$('awards-summary').insertAdjacentHTML('beforeend',`<h3>Feedback released to your team</h3>${Object.values(result.feedback).flat().map(note=>`<p>${esc(note)}</p>`).join('')}`);}}
function renderRecord(parent,data){const dl=document.createElement('dl');for(const [key,value]of Object.entries(data)){if(['ballots','scorecards','privateNotes'].includes(key))continue;const dt=document.createElement('dt');dt.textContent=key.replace(/([A-Z])/g,' $1');const dd=document.createElement('dd');if(value&&typeof value==='object'){if(Array.isArray(value))dd.textContent=value.map(x=>typeof x==='object'?x.name||x.seat||x.winner||'See event details':String(x)).join(', ');else renderRecord(dd,value);}else dd.textContent=String(value??'—');dl.append(dt,dd);}parent.append(dl);}
function fixtureCards(fixtures,draft=false){return (fixtures||[]).map(f=>`<article><h3>Round ${f.round} · ${esc(teamName(f.affirmativeTeamId))} / ${esc(teamName(f.negativeTeamId))}</h3><p>${esc(humanState(f.status))}${f.winnerTeamId?` · Winner: ${esc(teamName(f.winnerTeamId))}`:''}</p><p>Motion: ${esc(state.event.motions.find(m=>m.id===f.motionId)?.title || (f.motionId?'Released in match':'Assign before this match'))}</p>${f.requiresReview?'<p role="alert">An earlier result was corrected. An official must review this pairing before it can continue.</p>':''}<div class="actions">${!draft&&host()&&!f.matchId&&f.status==='SCHEDULED'&&!f.requiresReview?button('Set up this pairing','fixture-match',`data-fixture="${esc(f.id)}"`):''}${!draft&&f.matchId?button('Open match','select-match',`data-match="${esc(f.matchId)}"`):''}${!draft&&host()&&f.requiresReview?button('Review affected pairing','fixture-review',`data-fixture="${esc(f.id)}"`):''}</div></article>`).join('<hr>');}
function renderSchedule(){const e=state.event,t=e.eventAwards;$('schedule-content').innerHTML=`<div class="section-heading"><h2>Matches &amp; standings</h2><div class="actions">${host()?button('Set up match','match')+button('Generate pairings','fixtures')+button('Event report PDF','export','data-kind="event_report"')+button('End event','end-event'):''}</div></div><p>Sequential matches are the default. Provisional or unresolved results cannot advance a dependent official match.</p>${e.matches.map(m=>m.officialRecordsExpired?`<article><h3>${esc(m.title)}</h3><p>Official records expired under the approved retention policy. Scores, rules and downloads are no longer available.</p></article>`:`<article><h3>${esc(m.title)}</h3>${m.rematchOf?`<p>Rematch of ${esc(e.matches.find(prior=>prior.id===m.rematchOf)?.title||'an unresolved match')}</p>`:''}${m.rematchId?button('Open linked rematch','select-match',`data-match="${esc(m.rematchId)}"`):''}<p>${esc(humanState(m.phase))} · ${esc(m.rules.judgingMode)}${m.requiresReview?' · Correction review required':''}</p>${button('Open match','select-match',`data-match="${esc(m.id)}"`)}${host()?button('Advance to match','advance-match',`data-match="${esc(m.id)}"`):''}</article>`).join('<hr>')}<hr>${e.fixtureDraft?.needsReview?`<section><h3>Review draft pairings</h3>${fixtureCards(e.fixtureDraft.fixtures,true)}<p>${(e.fixtureDraft.idleSlots||[]).map(slot=>esc(`Round ${slot.round}: ${teamName(slot.teamId)} rests`)).join('; ')}</p>${button('Publish reviewed pairings','publish-fixtures')}</section><hr>`:''}<h3>Published pairings</h3>${fixtureCards(e.fixtures)||'<p>No published pairings.</p>'}<hr><h3>Standings</h3>${e.standings?.rows?.length?`<div class="table-scroll"><table><thead><tr><th>Rank</th><th>Team</th><th>Wins</th><th>Played</th><th>Comparable mean</th></tr></thead><tbody>${e.standings.rows.map(row=>`<tr><td>${row.rank}${row.tied?' (tied)':''}</td><td>${esc(teamName(row.teamId))}</td><td>${row.wins}</td><td>${row.played}</td><td>${esc(row.meanScore?.display??'Unavailable')}</td></tr>`).join('')}</tbody></table></div><p>Wins first; complete mutual mini-league next; comparable mean score next. Any remaining qualification tie needs the declared tie resolution.</p>`: '<p>No final standings yet.</p>'}<hr><h3>Tournament awards</h3><p>At least ${t?.minimumMatches||2} actual completed comparable matches are required. Different rubrics are evaluated separately.</p>${t?.reason?`<p>${esc(t.reason)}</p>`:''}${(t?.comparableGroups||[]).map((group,i)=>`<section><h3>Comparable rubric group ${i+1}</h3>${awardsSummary(group,true)}${group.bestDebater?.eligibleRunoffJudgeIds?.includes(e.myId)&&['RUNOFF_REQUIRED','AWAITING_RUNOFF'].includes(group.bestDebater.status)?button('Submit tournament runoff nomination','tournament-nominate',`data-group="${i}"`):''}</section>`).join('')||'<p>No eligible comparable group yet.</p>'}`;}
function renderHelp(){const m=currentMatch();$('help-content').innerHTML=`<div class="columns"><section><h2>Host &amp; moderator</h2><p>Confirm seats and neutral officials. Release the motion to both teams together. Explicitly start each stage; Next loads a ready clock. During questioning, both assigned speakers receive microphone permission. A grant never activates another person’s device.</p><p>Moderator script: “The motion is before the house. We now invite the assigned speaker. The questioning period includes both questions and answers. At the end, the panel will deliberate under the accepted rules.”</p><h2>Speaker</h2><p>Check in, verify your microphone, and accept your team’s rules as captain. Choose Mic when your floor permission is ready. Use Technical help if media fails; disconnection does not automatically forfeit the match.</p></section><section><h2>Judge</h2><p>Save private notes during speeches. Explicitly enter every score, review, and submit when final ballots open. Missing scores are not zero. A tied scorecard needs a reasoned choice; a tied panel remains unresolved under the declared process.</p><h2>Observer</h2><p>Camera begins off. Request the floor before speaking. Audience voting needs checked-in observer eligibility at poll opening; it never decides the official winner.</p></section></div><hr><h2>Connection and device help</h2><p>Enter room before turning on devices. If sound is blocked, use Enable sound. Screen audio depends on the browser and selected capture source; screen video alone does not prove shared audio. If an effect fails, camera stays safe and audio can continue. Select None explicitly only if you consent to showing your background.</p><div class="actions">${button('Request help or ruling','request-help')}${button('Retry last unconfirmed action','retry')}${host()&&m?.tieResolution?.rematchAvailable?button('Create linked rematch','rematch'):''}${moderationOfficial()?button('Record approved accommodation','record-accommodation')+button('End match / exceptional conclusion','conclude')+button('Substitute registered reserve','substitute'):''}</div><hr><h2>Help queue</h2>${(m?.incidents || []).map(i=>`<article><p>${esc(i.kind || i.type)} · ${esc(i.reason)} · ${esc(i.status || i.state)}</p>${moderationOfficial()?button('Acknowledge / resolve','resolve-incident',`data-incident="${esc(i.id)}"`):''}</article>`).join('')||'<p>No visible requests.</p>'}<hr><h2>Written records</h2>${state.event.canManageRetention?button('Review retention policy','retention')+button('Clean up eligible expired records','cleanup'):''}<p>Current policy: ${state.event.retention?.approved?'Approved':'Awaiting owner approval'}${state.event.retention?.hold?' · Documented hold active':''}. Chat ${state.event.retention?.chatDays} days; evidence ${state.event.retention?.evidenceDays} days; official records ${state.event.retention?.officialDays} days.</p><p>Standard record-keeping periods: chat and unsubmitted notes 30 days after event end; evidence 90 days; official scorecards, results, rules and activity records 365 days. An approved dispute hold can suspend deletion. Recording, transcription and livestreaming are not enabled.</p>`;}

async function guarded(fn){try{return await fn();}catch(error){status(error.message,true);}}
const media=new DebateMedia({audioRoot:$('audio-elements'),presentation:$('presentation'),onIssue:message=>status(message,true),onState:value=>{
  applyPersonalAudio();
  $('media-status').textContent=value.joined?'Connected. Your devices follow your choices and the current floor.':value.state==='disconnected'?'You are outside the call. The competition record remains saved.':`Room connection: ${value.state}`;
  for(const [key,label,on]of [['mic','Mic',value.microphone],['camera','Camera',value.camera],['share','Share',value.share]]){$(key).setAttribute('aria-pressed',String(on));$(key).textContent=`${label}${key==='share'?'':on?' on':' off'}`;$(key).disabled=!value.joined;}
},onVideo:(identity,video,label)=>{const tile=[...state.tiles.values()].find(t=>t.dataset.identity===identity);if(!tile)return;if(video&&video.parentElement!==tile)tile.prepend(video);tile.querySelector('.caption small').textContent=label;}});

