  'invite':()=>openDialog('Create invitation',`<label>Role<select name="role">${['observer','debater','judge','moderator','timekeeper','cohost','coach','reserve'].map(r=>option(r,r)).join('')}</select></label>${field('Intended verified email (required for privileged automatic assignment)','email','','email')}<label class="inline"><input name="requiresApproval" type="checkbox" checked>Host approves privileged role after sign-in</label>`,async form=>{const result=await command('create_invite',{role:form.get('role'),boundEmail:form.get('requiresApproval')==='on'?undefined:form.get('email')||undefined});state.freshInvite={...result,eventId:state.event.id};setTimeout(()=>openDialog('Invitation ready',`<p>Share this invitation only with the intended participants. It can be revoked from People.</p><textarea readonly rows="4">${esc(`${location.origin}${location.pathname}#event=${state.event.id}&invite=${result.secret || result.code}`)}</textarea><p>Code: ${esc(result.code || result.secret)}</p>${button('Preview invitation email','email-invitation')}`,async()=>{},'Done'),0);},'Create invitation'),
