  'invite-private':b=>openDialog('Invite moderator into private room',`<p>${esc(personName(currentMatch().moderatorId))} will be visibly invited to ${b.dataset.space==='judges'?'judge deliberation':sideName(b.dataset.space)+' preparation'} for the current phase. This does not disclose previous private notes.</p><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label><label class="inline"><input type="checkbox" required>I confirm this invitation</label>`,form=>command('invite_private_room',matchPayload({space:b.dataset.space,moderatorId:currentMatch().moderatorId,reason:form.get('reason'),confirmed:true})),'Invite moderator'),
