  'submit-ballot':()=>{const values=scoreFormData();openDialog('Review final ballot',`<p>Your final ballot will be submitted as your own judging decision. Confirm that every score and your explanation are complete.</p><p>${esc(values.reason || 'No explanation entered')}</p><label class="inline"><input type="checkbox" required name="confirmed">I reviewed my scorecard and decision</label>`,async()=>{await command('submit_ballot',matchPayload({...values,confirmed:true}));state.judgeDirty=false;renderJudge();},'Submit final ballot');},
  'nominate':()=>{const m=currentMatch(),n=m.nominationStatus;const runoff=['RUNOFF_REQUIRED','AWAITING_RUNOFF'].includes(n?.status);const candidates=runoff?n.candidates:SEATS;openDialog(runoff?'Best Debater nomination runoff':'Nominate Best Debater',`<p>${runoff?'Choose only among the tied top nominees.':'Nominate one actual speaker with a reasoned explanation.'}</p><label>Speaker<select name="seat">${candidates.map(s=>option(s,s+' · '+personName(m.seats[s]),(runoff?m.myNominationRunoff:m.myNomination)?.nomineeId)).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="2000">${esc((runoff?m.myNominationRunoff:m.myNomination)?.reason||'')}</textarea></label>`,form=>command('nominate_award',matchPayload({nomineeId:form.get('seat'),reason:form.get('reason'),runoff})));},
  'panel-change':()=>openDialog('Panel change / recusal',`${selectPerson('Judge leaving the panel','removeJudgeId')}${selectPerson('Substitute judge (optional)','addJudgeId')}<label class="inline"><input type="checkbox" name="observed">The substitute observed all required debate stages</label><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>command('change_panel',matchPayload({judgeIds:[...currentMatch().judgeIds.filter(p=>p!==form.get('removeJudgeId')),...(form.get('addJudgeId')?[form.get('addJudgeId')]:[])],observedJudgeIds:form.get('observed')==='on'?[form.get('addJudgeId')]:[],reason:form.get('reason')}))),
  'substitute':()=>openDialog('Substitute registered reserve',`<p>The reserve must check in and complete a microphone check or approved accommodation first. Both captains must accept the changed assignment. An affected active stage becomes a fresh ready attempt; earlier scores and attempts retain their original speaker.</p><label>Seat<select name="seat">${SEATS.map(s=>option(s,s)).join('')}</select></label>${selectPerson('Registered reserve','memberId')}<label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>command('substitute_speaker',matchPayload(readValues(form)))),
  'edit-sanction-policy':b=>sanctionPolicyDialog(b.dataset.sanction),
