  'schedule-check-in':()=>{const m=currentMatch();openDialog('Schedule match check-in',`${field('Check-in time in '+state.event.timezone,'scheduledCheckInAt',eventLocalInput(m.checkIn?.scheduledAt,state.event.timezone),'datetime-local')}<p>Leave empty for an unscheduled match. The default grace is ten minutes after this time.</p>`,form=>command('update_match_schedule',matchPayload({scheduledCheckInAt:form.get('scheduledCheckInAt')?eventInstant(form.get('scheduledCheckInAt'),state.event.timezone):null})),'Save check-in time');},
  'record-no-show':()=>{const m=currentMatch(),assigned=[...new Set([...Object.values(m.seats),...m.judgeIds,m.moderatorId,m.timekeeperId,m.chiefId].filter(Boolean))].filter(id=>!m.checkIn?.attendance?.[id]);openDialog('Record absent participant',`<p>The scheduled grace period elapsed. This records your finding; it does not declare a forfeit.</p><label>Absent participant<select name="memberId" required>${assigned.map(id=>option(id,personName(id))).join('')}</select></label><label>Reason / contact attempts<textarea name="reason" required maxlength="2000"></textarea></label><label class="inline"><input type="checkbox" required>I verified this person has not arrived</label>`,form=>command('record_no_show',matchPayload({...readValues(form),confirmed:true})),'Record finding');},
