  'retention':()=>{const policy=state.event.retention;openDialog('Review retention policy',`<p>These settings apply only to this event after its actual end. A documented hold suspends deletion. Changes to this policy require approval from Due Diligence.</p>${[['Room activity records','operationalDays'],['Chat and unsubmitted drafts','chatDays'],['Evidence','evidenceDays'],['Official scorecards, rules, results and activity records','officialDays']].map(([label,key])=>field(label+' (days)',key,policy[key],'number','min="1" max="3650" required')).join('')}<label class="inline"><input type="checkbox" name="approved" ${policy.approved?'checked':''}>Due Diligence approved this policy</label><label class="inline"><input type="checkbox" name="hold" ${policy.hold?'checked':''}>Apply documented dispute/legal hold</label><label>Reason / hold reference<textarea name="reason" required maxlength="2000">${esc(policy.holdReason||'')}</textarea></label>`,form=>command('set_retention',{...Object.fromEntries(['operationalDays','chatDays','evidenceDays','officialDays'].map(key=>[key,Number(form.get(key))])),approved:form.get('approved')==='on',hold:form.get('hold')==='on',reason:form.get('reason')}),'Save policy');},
