function certificateDialog(){openDialog('Issue certificate',`<label>Confirmed participant<select name="participantId">${state.event.members.filter(p=>currentMatch()?.checkIn?.attendance?.[p.id]&&!p.removed).map(p=>option(p.id,p.displayName)).join('')}</select></label><label>Certificate<select name="awardKey"><option value="">Recorded participation</option><option value="bestSpeaker">Best Speaker</option><option value="bestInterpellator">Best Interpellator</option><option value="bestRebuttalSpeaker">Best Rebuttalist</option><option value="bestDebater">Best Debater</option></select></label><p>Only confirmed final award recipients can receive an award certificate.</p>`,form=>command('create_export',matchPayload({kind:'certificate',participantId:form.get('participantId'),awardKey:form.get('awardKey')||undefined})),'Create certificate');}
async function downloadFile(route,params,fallback){const generation=state.accountGeneration,view=state.viewGeneration,eventId=state.event?.id,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),18000);try{const response=await fetch(apiBase+route+'?'+new URLSearchParams(params),{headers:{Authorization:'Bearer '+state.session.access_token},cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error('This download is unavailable or your permission changed.');const blob=await response.blob();if(generation!==state.accountGeneration||view!==state.viewGeneration||eventId!==state.event?.id)throw new Error('Your account or event changed; this download was discarded.');const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=response.headers.get('X-Debate-Filename')||fallback;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),20000);}finally{clearTimeout(timeout);}}
async function downloadEvidence(evidenceId){return downloadFile('/debate-room/evidence/download',{eventId:state.event.id,matchId:currentMatch().id,evidenceId},'evidence');}
function roleDialog(b){const p=state.event.members.find(p=>p.id===b.dataset.person);openDialog('Assign event roles',`<p>${esc(p.displayName)}</p><fieldset><legend>Roles</legend>${['observer','debater','judge','moderator','timekeeper','cohost','coach','reserve',...(p.id===state.event.ownerId?['host']:[])].map(role=>`<label class="inline"><input type="checkbox" name="roles" value="${role}" ${p.roles.includes(role)?'checked':''} ${role==='host'?'disabled':''}>${esc(humanState(role))}</label>`).join('')}</fieldset><label>Team association (required for coach or reserve)<select name="teamId">${option('','No team',p.teamId)}${state.event.teams.map(t=>option(t.id,t.name,p.teamId)).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>{const roles=form.getAll('roles');if(p.id===state.event.ownerId)roles.push('host');if(roles.some(r=>['coach','reserve'].includes(r))&&!form.get('teamId'))throw new Error('Choose the registered team for its coach or reserve.');return command('assign_role',{memberId:p.id,roles,teamId:form.get('teamId')||null,reason:form.get('reason')});});}
function eventDialog(event){openDialog(event?'Edit event':'Create a debate',`${field('Event title','title',event?.title || '','text','required maxlength="160"')}<label>Description<textarea name="description" maxlength="4000">${esc(event?.description || '')}</textarea></label><div class="columns">${field('Timezone','timezone',event?.timezone || 'Asia/Manila')}${field('Language','language',event?.language || 'English')}</div><details><summary>Event contact shown to admitted participants</summary>${field('Contact name','contactName',event?.contact?.name||'','text','maxlength="120"')}${field('Contact email','contactEmail',event?.contact?.email||'','email','maxlength="254"')}${field('Contact website','contactUrl',event?.contact?.url||'','url','maxlength="2000"')}</details>${field('Scheduled start in the selected timezone (optional)','scheduledAt',eventLocalInput(event?.scheduledAt,event?.timezone||'Asia/Manila'),'datetime-local')}<label>Visibility<select name="visibility">${option('unlisted','Unlisted — invitation or code',event?.visibility || 'unlisted')}${option('public','Discoverable by signed-in members',event?.visibility)}</select></label><label class="inline"><input name="rehearsal" type="checkbox" ${event?.rehearsal?'checked':''}>Practice debate (excluded from competition standings)</label>`,form=>command(event?'update_event':'create_event',{...readValues(form),contact:{name:form.get('contactName'),email:form.get('contactEmail'),url:form.get('contactUrl')},scheduledAt:eventInstant(form.get('scheduledAt'),form.get('timezone')),rehearsal:form.get('rehearsal')==='on'},event?.id),'Save event');}
function matchDialog(fixture){if(state.event.teams.length<2)throw new Error('Confirm at least two three-speaker teams in People first.');
  openDialog(fixture?'Set up scheduled match':'Set up match',`${field('Match title','title',`Match ${state.event.matches.length+1}`)}<div class="columns">${['affirmative','negative'].map(s=>`<label>${sideName(s)} team<select name="${s}" ${fixture?'disabled':''}>${state.event.teams.map((t,i)=>option(t.id,t.name,fixture?.[`${s}TeamId`] || state.event.teams[s==='affirmative'?0:1]?.id)).join('')}</select></label>`).join('')}</div><label>Motion<select name="motionId" ${fixture?.motionId?'disabled':''}>${state.event.motions.map(m=>option(m.id,m.title,fixture?.motionId)).join('')}</select></label><fieldset><legend>Panel</legend><p>The default is one or three judges. An even panel can tie; the declared default is one same-panel reconsideration, then a linked rematch.</p>${[1,2,3].map(n=>selectPerson(n===1?'Required neutral judge':'Additional judge (optional)',`judge${n}`)).join('')}<label class="inline"><input type="checkbox" name="evenPanelAccepted">If I choose two judges, I accept the even-panel warning and declared tie procedure</label></fieldset><details><summary>Officials and closing assignments</summary>${selectPerson('Moderator (defaults to first judge)','moderatorId')}${selectPerson('Timekeeper (defaults to moderator)','timekeeperId')}${selectPerson('Chief adjudicator (defaults to first judge)','chiefId')}<label>Affirmative closing seat<select name="closingA"><option value="">Team captain (default)</option>${['A1','A2','A3'].map(s=>option(s,s)).join('')}</select></label><label>Negative closing seat<select name="closingN"><option value="">Team captain (default)</option>${['N1','N2','N3'].map(s=>option(s,s)).join('')}</select></label></details><label>Decision method<select name="judgingMode">${option('majority','Full scorecards — majority ballots')}${option('simple','Simple winner ballots')}${option('aggregate','Full scorecards — aggregate scores')}</select></label>`,form=>{const a=state.event.teams.find(t=>t.id===(fixture?.affirmativeTeamId||form.get('affirmative'))),n=state.event.teams.find(t=>t.id===(fixture?.negativeTeamId||form.get('negative')));return command('create_match',{fixtureId:fixture?.id,title:form.get('title'),motionId:fixture?.motionId||form.get('motionId'),teamIds:{affirmative:a.id,negative:n.id},seats:Object.fromEntries([...a.speakerIds.map((p,i)=>[`A${i+1}`,p]),...n.speakerIds.map((p,i)=>[`N${i+1}`,p])]),captains:{affirmative:a.captainId,negative:n.captainId},closingSeats:{affirmative:form.get('closingA')||'A'+(a.speakerIds.indexOf(a.captainId)+1),negative:form.get('closingN')||'N'+(n.speakerIds.indexOf(n.captainId)+1)},judgeIds:[1,2,3].map(i=>form.get(`judge${i}`)).filter(Boolean),chiefId:form.get('chiefId')||undefined,evenPanelAccepted:form.get('evenPanelAccepted')==='on',moderatorId:form.get('moderatorId')||undefined,timekeeperId:form.get('timekeeperId')||undefined,rules:{judgingMode:form.get('judgingMode')}});},'Create match');}
function rulesDialog(){
  const m=currentMatch(),r=m.rules,locked=!!m.rulesLockedAt;
  openDialog('Edit match rules',`<p>Changing accepted rules requires fresh captain acknowledgments. Live changes require an explicit pause and reason. The decision method and scoring rubric stay fixed after start.</p>
    <label>Decision method<select name="judgingMode" ${locked?'disabled':''}>${['majority','simple','aggregate'].map(v=>option(v,v,r.judgingMode)).join('')}</select></label>
    <div class="columns">${[['Constructive minutes','constructiveMs'],['Questioning minutes','interpellationMs'],['Closing minutes','rebuttalMs'],['Preparation minutes','preparationMs']].map(([label,k])=>field(label,k,r[k]/60000,'number','min="0" max="180" step="0.5" required')).join('')}</div>
    <label class="inline"><input name="closingBreakEnabled" type="checkbox" ${r.closingBreakEnabled?'checked':''}>Preparation break before closing</label>${field('Closing break minutes','closingBreakMs',r.closingBreakMs/60000,'number','min="0" max="180" step="0.5" required')}
    <label class="inline"><input name="observerCameras" type="checkbox" ${r.observerCameras?'checked':''}>Allow observer cameras uniformly</label>
    <details><summary>Rubric and case labels</summary><fieldset ${locked?'disabled':''}><legend>Scoring rubric — weights total 100</legend>${Object.keys(r.rubric.weights).map(k=>`<section>${field('Criterion label',`label.${k}`,r.rubric.labels[k])}${field('Weight',`weight.${k}`,r.rubric.weights[k],'number','min="0" max="100" step="0.01" required')}<label>Judge guidance<textarea name="help.${k}" required maxlength="2000">${esc(r.rubric.help[k])}</textarea></label></section>`).join('')}</fieldset>${r.caseLabels.map((v,i)=>field(`Case label ${i+1}`,`case${i}`,v)).join('')}</details>
    <label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>{
      const rules=copy(r);for(const k of ['constructiveMs','interpellationMs','rebuttalMs','preparationMs','closingBreakMs'])rules[k]=Number(form.get(k))*60000;
      if(!locked){rules.judgingMode=form.get('judgingMode');for(const k of Object.keys(r.rubric.weights)){rules.rubric.weights[k]=Number(form.get(`weight.${k}`));rules.rubric.labels[k]=form.get(`label.${k}`);rules.rubric.help[k]=form.get(`help.${k}`);}}
      rules.closingBreakEnabled=form.get('closingBreakEnabled')==='on';rules.observerCameras=form.get('observerCameras')==='on';rules.caseLabels=[0,1,2].map(i=>form.get(`case${i}`));
      return command(m.rulesLockedAt?'amend_rules':'update_rules',matchPayload({rules,reason:form.get('reason')}));
    });
}

async function transitionSpace(space){if(state.mediaTransition)return;state.mediaTransition=true;try{await media.suspend();await command('enter_space',matchPayload({space,deviceId}));await enterMediaWhenReady();}finally{state.mediaTransition=false;}}
async function enterMediaWhenReady(){const result=await request('/debate-room/media',{eventId:state.event.id,matchId:currentMatch().id,deviceId});if(result.event)adopt(result.event);await media.join(result.credential || result);renderLive();}
async function reconcileMedia(){if(state.mediaTransition||!media.credential||!state.event)return;const m=currentMatch(),session=m?.myMedia;if(!session||['left','failed'].includes(session.status)){await media.leave();return;}if(media.joined&&session.identity===media.credential.identity&&session.status==='ready')return;state.mediaTransition=true;try{await media.suspend();await enterMediaWhenReady();}catch(error){status(error.message,true);}finally{state.mediaTransition=false;}}
async function leaveCurrentMedia(){const match=currentMatch(),hadSession=match?.myMedia,matchId=match?.id,eventId=state.event?.id,view=state.viewGeneration;await media.leave();if(hadSession&&eventId===state.event?.id&&view===state.viewGeneration&&matchId===currentMatch()?.id&&!state.busy)await command('leave_media',{matchId,deviceId},eventId);}
async function signOutCleanup(){
  state.accountGeneration++;clearSensitiveViews();state.mutedPeople=new Set();state.blockedPeople=new Set();state.pinnedTile=null;state.messageHistory.clear();state.historyDone.clear();state.freshInvite=null;
  clearTimeout(state.draftTimer);state.judgeDirty=false;state.event=null;state.session=null;state.pending=null;state.sync=null;
  $('dialog').close();$('dialog-fields').replaceChildren();$('events').replaceChildren();$('discover-events').replaceChildren();
  for(const key of ['overview-content','participants-content','rules-content','judge-content','vote-content','messages','evidence-list','results-content','schedule-content','help-content'])$(key).replaceChildren();
  $('event').hidden=true;$('lobby').hidden=false;$('account').textContent='Sign in';await media.leave();
}
async function boot(){
  if(localRehearsal){const identity=await fetch('/__rehearsal/identity',{cache:'no-store'}).then(r=>r.json());state.session={access_token:identity.token,user:identity.user};}
  else if(!state.client) {if(!config.supabase?.url || !globalThis.supabase?.createClient)throw new Error('Secure sign-in could not load. Return to Due Diligence and retry.');const storage=globalThis.DueDiligenceAuthSessionStorage?.prepare?.(config.supabase.url);state.client=globalThis.supabase.createClient(config.supabase.url,config.supabase.publishableKey,{auth:{flowType:'pkce',persistSession:true,storage,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await state.client.auth.getSession();if(error)throw error;state.session=data.session;state.client.auth.onAuthStateChange((_event,session)=>{if(state.session?.user?.id!==session?.user?.id)setTimeout(()=>guarded(async()=>{await signOutCleanup();state.session=session;if(session)await boot();}),0);else state.session=session;});}
  if(!state.session){status('Sign in to create or join a debate. Camera and microphone stay off.');return;}
  loadPersonal();$('account').textContent=state.session.user?.user_metadata?.full_name || 'Signed in';await loadEvents();status('Create a match or join with an invitation.');
  const params=new URLSearchParams(location.hash.slice(1));const eventId=params.get('event');const invite=params.get('invite');state.matchId=params.get('match');
  if(invite&&eventId){history.replaceState(null,'',`${location.pathname}#event=${encodeURIComponent(eventId)}`);const result=await request('/debate-room/claim',{eventId,secret:invite,idempotencyKey:id()});adopt(result.event,true);}else if(eventId)await openEvent(eventId);
}

document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(b)guarded(()=>actions[b.dataset.action]?.(b));});
