async function openDeviceDialog(){
  const generation=media.generation,devices=await media.devices();
  if(generation!==media.generation)return;
  const choices=(kind,label,selected)=>{const available=devices.filter(device=>device.kind===kind);return option('',`Default ${label.toLowerCase()}`,selected)
    +(selected&&!available.some(device=>device.deviceId===selected)?option(selected,`Selected ${label.toLowerCase()} (unavailable)`,selected):'')
    +available.map((device,index)=>option(device.deviceId,device.label||`${label} ${index+1}`,selected)).join('');};
  openDialog('Devices & background',`<p>No device starts until you enable it. Shared audio depends on the browser and capture source.</p><label>Camera<select name="cameraDevice">${choices('videoinput','Camera',media.cameraDevice)}</select></label><label>Microphone<select name="microphoneDevice">${choices('audioinput','Microphone',media.microphoneDevice)}</select></label><label>Background<select name="effect">${['none','blur','brand','custom'].map(x=>option(x,x==='none'?'None — show my actual background':x,media.effect)).join('')}</select></label><label>Custom image (kept on this device)<input type="file" name="image" accept="image/png,image/jpeg,image/webp"></label>`,async form=>{
    if(generation!==media.generation)throw new Error('The room connection changed. Reopen Devices before saving.');
    const effect=form.get('effect'),image=form.get('image');
    if(effect!==media.effect||image?.size)await media.setEffect(effect,image);
    if(generation!==media.generation)return;
    await media.selectDevices({cameraDevice:form.get('cameraDevice'),microphoneDevice:form.get('microphoneDevice')});
  });
}
$('devices').onclick=()=>guarded(openDeviceDialog);
