$('message-form').onsubmit=event=>{event.preventDefault();guarded(async()=>{const text=new FormData(event.currentTarget).get('text');let channel=$('channel').value;if(channel==='team'){const side=myTeamSide();if(!side)throw new Error('Only assigned team participants can use a team channel.');channel='team:'+side;}else if(channel==='main')channel='public';await command('send_message',matchPayload({channel,text}));event.target.reset();});};
async function submitEvidence(form){if(state.evidenceUploading)return;state.evidenceUploading=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{const generation=state.accountGeneration,view=state.viewGeneration,eventId=state.event.id,matchId=currentMatch().id;const values=new FormData(form),file=values.get('file');let channel=values.get('channel');if(channel==='team'){const seat=Object.keys(currentMatch().seats).find(s=>currentMatch().seats[s]===state.event.myId);if(!seat)throw new Error('Only assigned speakers can share to a team.');channel=seat[0]==='A'?'team:affirmative':'team:negative';}let attachment;if(file?.size){if(file.size>10485760)throw new Error('The file must be 10 MB or smaller.');status('Uploading private evidence…');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),18000);try{const response=await fetch(apiBase+'/debate-room/evidence/upload?'+new URLSearchParams({eventId:state.event.id,matchId:currentMatch().id,channel}),{method:'POST',headers:{Authorization:'Bearer '+state.session.access_token,'Content-Type':file.type,'X-Debate-Filename':file.name.replace(/[^a-zA-Z0-9._ -]/g,'_')},body:file,cache:'no-store',signal:controller.signal});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error?.message||'The file upload was not confirmed.');attachment=result.attachment;}finally{clearTimeout(timeout);}}if(generation!==state.accountGeneration||view!==state.viewGeneration||state.event?.id!==eventId||currentMatch()?.id!==matchId)throw new Error('Your account or match changed; reselect this evidence in the current event.');if(!attachment&&!values.get('sourceUrl'))throw new Error('Add a source link or a supported file.');await command('share_evidence',matchPayload({title:values.get('title'),description:values.get('description'),sourceUrl:values.get('sourceUrl')||undefined,channel,attachment,ruling:values.get('ruling')||undefined}));form.reset();}finally{state.evidenceUploading=false;if(submit)submit.disabled=false;}}
$('evidence-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;guarded(()=>submitEvidence(form));};
